        instruction: '听一段对冠军自行车手 Anna Taylor 的采访，每题从 A/B/C 中选出最佳答案。',
        type: 'mcq',
        audio: '/audio/pet-schools1/test-1/part-4.mp3',
        transcript: "Interviewer: Anna Taylor's a teenager and already a champion cyclist. Anna, when did you first get into cycling?\nAnna: Only a few years ago. I've always been keen on sports - I've tried everything from running to ice-skating - but I never tried to be good at anything in particular. After I went to support a friend cycling in a competition. I decided to. try it myself - and loved it. Since then, it's been a big part of my life.\nInterviewer: Is it hard to practise cycling and do your schoolwork?\nAnna: Studying's difficult when there's a big competition coming up. I still have to attend all my lessons - and the teachers are very strict about giving in homework on time. I manage to get it done somehow. I have cycle practice in the afternoons after school, so then I have to work till bedtime once I've had dinner with my family.\nInterviewer: You do a lot of track cycling in a stadium. Tell me about that.\nAnna: We cycle around a special indoor track and the fastest person wins. When cyclists race on the road, speed is important too of course, and being strong''s also essential. I think more skills are needed for track cycling - watching one another and waiting for a chance to move to the front. It takes a lot of experience to get it right.\nInterviewer: Do you like cycling with teammates in road races?\nAnna: Yes. They're a great group of people, and we all have different styles. When things go wrong it's not always easy to see the funny side, so it's nice to know the others are finding it as stressful as I am. We encourage each other. I'm beginning to understand just how important that is.\nInterviewer: How was your last road race?\nAnna: My team actually came second. But just before the start of the race, I had to make a quick phone call, and when I'd finished the call, 200 cyclists were racing past me - I was shocked to see it had already started! I ran to my bike, and then I saw my teammate had a tyre problem. But despite all that, things didn't go too badly in the end!\nInterviewer: What's your advice for anyone wanting to become a champion cyclist?\nAnna: Well, if all I did was cycling, life would be extremely difficult. It's a good idea to have interests other than sport. I don't want competing in races to be everything. When things go wrong in training, you have to remind yourself there are more things to life than winning competitions. Now listen again. [repeat]",
