        instruction: '听一段老师介绍去城市博物馆研学的安排，在笔记空格中填入 1-2 个词、数字、日期或时间。',
        type: 'blanks',
        audio: '/audio/pet-schools1/test-2/part-3.mp3',
        transcript: "Woman: Right, everyone. I'm going to tell you about our trip to the City Museum. The museum isn't far - it'll only take us about 20 minutes to get there. There'll be several events during the day and you'll have the chance to walk around the museum for at least 50 minutes. To begin with though. we'll listen to the museum director for about 30 minutes, telling us about what there is to see there. Her name is Jane Witton. She's asked students to send questions by email before the trip, which she'll try to answer. I'll give you her email address: it's witton@ museum.org. That's W-I-double T-O-N. Usually in a museum you're not allowed to touch what's on display, but on this visit, we are! You'll all work in groups, and each group will be given pots to pick up and look at, and think about what they were used for. They're very old so be careful! You'll study some ancient rings too, although I'm afraid they'll stay in their glass case. The museum also has a Technology Centre for education and research. You'll be able to find out lots of interesting facts. Rather than using computers, though. tablets will be provided. You can work on these to search for information. When you've finished your research, for the final activity you'll do a quiz to see how much you can remember. Don't worry, it's not a test, or even a competition - it's just for fun. It'll be interesting to see what you've learned. When we get back to school, I'd like you to design and make something to show other students. The museum has sent us some of their postcards, which you can use to give you ideas for the posters I want you to draw. OK, I think that's everything ... [fade] Now listen again. [repeat]",
