      4: {
        title: 'Part 4 · 访谈选择',
        instruction: '听一段对参加青少年赛道驾驶体验的女孩 Jenna 的采访，每题从 A/B/C 中选出最佳答案。',
        type: 'mcq',
        audio: '/audio/pet-schools1/test-3/part-4.mp3',
        transcript: "Man: Jenna, you went on a driving experience day for teenagers at a race track recently. Why?\nGirl: Well, people often think driving fast cars is for boys. My parents bought my brother a ticket for his birthday. I was so jealous and, as he already drives a car, he said I could take his place. I'd definitely recommend it - my best friend thought it sounded cool so she's going to go too.\nMan: How did you feel when you arrived at the race track?\nGirl: I waited in reception till everyone who was driving that day arrived - a couple of girls my age and two older teenagers - that was it - not what I'd expected, but I guess very few people knew about it. I thought I'd get in a car straight away but there was stuff to do first, which was a pity! My instructor was cool, though - he said he used to be a racing driver.\nMan: What did you have to do before driving?\nGirl: We had to watch a video about staying safe. That's when I realised I had no idea how to drive! I was slightly anxious, but I never considered not doing it, like one boy. We were told we'd have a practice session to get used to the car before going out on the track, which I was glad about.\nMan: How did you feel out on the track?\nGirl: Brilliant! The car was automatic so I didn't have to worry about using lots of controls. It was like those racing computer games - you can't see what's coming next. I've heard there's a game based on that race track, actually. The instructor was sitting right next to me and kept telling me to brake when I wanted to speed up - very annoying!\nMan: Were you happy about everything else?\nGirl: Well, yes and no. I knew the car would be super-powerful - that's why I went. I drove for around ten minutes. It seemed much longer cos you concentrate so hard. The only thing was that I was completely exhausted when I finished. just from driving for such a short time!\nMan: What would you do differently next time?\nGirl: If there is a next time, I'd probably do my best to learn what comes next as I was driving, so I'd be ready for a corner or a straight bit or whatever. The instructions I was given helped me to understand all the special driving techniques, so I didn't feel I had loads of questions I needed to ask.\nMan: Thanks, Jenna. Now listen again. [repeat]",
        items: [
          {
            q: 'Why did Jenna go on the driving experience day?',
            opts: ['A friend recommended it to her.', 'Someone gave her a ticket for her birthday.', 'Her brother said she could go instead of him.'],
            answer: 2,
            explanation: '"My parents bought my brother a ticket for his birthday. I was so jealous and, as he already drives a car, he said I could take his place"，哥哥让位她才去成的，选 C；好朋友只是听说后觉得酷也想同去，不是推荐给她的原因。',
          },
          {
            q: 'How did Jenna feel when she arrived at the race track?',
            opts: ["pleased to meet an instructor she'd heard of", 'surprised there were so few other drivers', 'disappointed by the car she was going to drive'],
            answer: 1,
            explanation: '当天的学员只有 "a couple of girls my age and two older teenagers – that was it – not what I\'d expected, but I guess very few people knew about it"，为人数之少感到意外，选 B；教练是分配的、人很酷，她没提听说过谁；对要先做室内活动有点遗憾，不是对车失望。',
          },
          {
            q: 'While Jenna was watching the video before driving, she',
            opts: ['suddenly felt nervous about what she was about to do.', 'almost changed her mind about going out in a car.', 'wished she had time to practise before going on the track.'],
            answer: 0,
            explanation: '看安全视频时才意识到自己完全不会开车："That\'s when I realised I had no idea how to drive! I was slightly anxious"，突然为接下来的动作紧张，选 A；她从没想过放弃（I never considered not doing it），而且赛前有练习环节，她感到庆幸。',
          },
          {
            q: 'When she was out on the race track, Jenna felt',
            opts: ['excited to recognise the track from a computer game.', "annoyed that she couldn't go faster.", "confused by the car's controls."],
            answer: 1,
            explanation: '"The instructor was sitting right next to me and kept telling me to brake when I wanted to speed up – very annoying!"，教练一直让她刹车、不能加速让她恼火，选 B；她说开起来像赛车游戏、还听说有游戏以该赛道为原型，不是认出赛道而兴奋；车是自动挡，操控并不复杂。',
          },
          {
            q: 'Jenna says that she was unhappy about',
            opts: ['how tired she felt after driving.', 'how long she was allowed to drive for.', 'how powerful the car was.'],
            answer: 0,
            explanation: '"The only thing was that I was completely exhausted when I finished, just from driving for such a short time!"，开完就累瘫是她唯一不满的地方，选 A；车超强马力正是她想去的原因，实际只开十分钟却因专注觉得漫长。',
          },
          {
            q: 'What would Jenna do differently if she drove again?',
            opts: ['ask more questions about driving techniques', 'listen more carefully to all the instructions', 'try to remember each part of the race track'],
            answer: 2,
            explanation: '"If there is a next time, I\'d probably do my best to learn what comes next as I was driving, so I\'d be ready for a corner or a straight bit or whatever"，想边开边记住赛道每一段，选 C；指导已帮她理解了驾驶技巧，她没觉得有很多问题要问，也并非没听清指导。',
          },
        ],
      },
