        title: 'Part 3 · 笔记填空',
        instruction: '听一段新闻记者 Mona Dawson 向学生介绍自己工作的讲话，在笔记空格中填入 1-2 个词、数字、日期或时间。',
        type: 'blanks',
        audio: '/audio/pet-schools2/test-2/part-3.mp3',
        transcript: "Woman: Hello, everybody. I'm here to tell you about my work as a news reporter. Some reporters study journalism at university, or subjects like politics and economics. I did history, and that's really useful for understanding the world today. After leaving university, I worked on a local newspaper, and got experience as a journalist. My first article actually went on the front page - but it was only about a new road. There weren't many exciting events to write articles on, like, say, a bank robbery or celebrity wedding. A news reporter must always be ready for a news story. Most reporters never go anywhere without a laptop, but I'm old-fashioned. I take a pen wherever I go, and I've lost my phone so many times! It's useful to have some paper too, but I can always find something to write on. Now I work on the news for a TV channel, and I sometimes interview famous people. The last one was a politician. I've just heard my next interview is with someone from a big transport company, but not the owner, or even a manager. Instead, it's with a lorry driver. I'm sure it'll be very interesting. To be a TV reporter, lots of personal qualities are useful. Some people say a strong voice, others think it's necessary to have a smart appearance. I'd say it's my memory that really helps. It's easy to forget things, so it's essential to have a good one. What about the future? I love writing and I'm planning a book. I'm interested in energy, and I believe we need to stop using oil so much. We know that the wind and the sea can produce energy, but the subject I'm going to explore is how we can use the sun to produce it for our needs. Any questions ... [fade] Now listen again. [repeat]",
