        type: 'mcq',
        audio: '/audio/pet-schools2/test-2/part-4.mp3',
        transcript: "Woman: I'm talking to Matt Luxton who spent four weeks as a volunteer at a rescue centre for sick elephants. Matt, how did you learn about the rescue centre?\nMan: I've always loved elephants. My mum was worried about the idea of me going away when I told her about the organisation. It was one of my school teachers who'd shown me the advert for it. Luckily, my best friend supported me and helped me persuade Mum to let me go.\nWoman: How did you pay for the trip?\nMan: Well, it wasn't cheap. My uncle offered to lend me the money, but I wanted to pay for myself. A surfboard business had opened in town, and I got a job there. I thought about selling some of my things online, but I managed to save enough money without having to do that.\nWoman: What was it like arriving at the elephant rescue centre?\nMan: It was evening when my plane landed and by the time I got to the rescue centre, all the elephants were asleep. The next day I was told there were over twenty of them! The welcome I got from the staff and the other volunteers was brilliant, I'll never forget it. It was too dark to look around the gardens when I got there. I've got some great photos of the gorgeous trees and flowers that it's known for.\nWoman: What was your first job there?\nMan: It's important to get used to the elephants slowly. So I could only watch when they were given a bath in the river - it looked such fun! Instead, I was asked to put all the stuff that the elephants were going to eat in buckets for them. I really wanted to work with the vets, who look after the elephants when they get sick, but you need qualifications for that.\nWoman: What was difficult about the experience?\nMan: I thought the heat would be hard. It was OK, though. We woke up at sunrise ready to start work - it's much cooler then. I met loads of people, but it wasn't easy to understand what they were saying. Strange - I'm usually pretty good at languages. I wasn't there long enough, I guess.\nWoman: And what did you learn about elephants?\nMan: They're wonderful creatures. I'd read so much about how clever they are, and what good memories they've got. But I just hadn't realised that no two elephants are the same, until I'd spent time with them. One elephant might be brave, another quite shy, and another good at looking after the young. That's what really impressed me.\nWoman: Thanks, Matt ... [fade] Now listen again. [repeat]",
