        audio: '/audio/pet-schools2/test-3/part-3.mp3',
        transcript: "Boy: Hi, everyone. I want to tell you about a boat trip I went on recently. My mum drove us to a little port called Seaville. There were loads of boats there taking people on trips. Their names all had connections with things in the sky. The one we chose was called Silver Star. There was a much bigger one called Golden Sun that I'd like to go on another time. You can choose how long you want to go on a boat trip for. Three and a half hours was enough for us, but some boats go out for as much as ten hours, and others as little as an hour and a half. You can see all sorts of things from the boat. At certain times of year, you might be lucky enough to see whales as they swim up the coast. We went at the wrong time for that, but a lovely group of dolphins came very close to us. We visited an island as part of the trip. There were some amazing cliffs, which looked very high, but even better were the caves there. They had lights in and we walked into several of them for a few hundred metres. If you'd like to go on a boat trip there, the captain of our boat said the best time to visit is in September. There's lots of wildlife around then, but avoid going in January as that's when the weather's really bad, and the crews all take their holidays. They're usually back by February. You can find out more by going to the website that has all the information on boat trips. The address is www dot robshaw dot islandboattrips dot com. I'll spell that for you ... it's R-O-B-S-H-A-W dot islandboattrips dot com. Thanks for listening! Now listen again. [repeat]",
