        transcript: "Man: We have a video blogger on the show today ~ someone who records and appears in their own videos on the internet. Amy Wu, who's only 19, has a popular video blog. Welcome, Amy.\nWoman: Hi.\nMan: So how did you get the idea of becoming a video blogger?\nWoman: I was 11, and I was off school with a bad cold. Because I was bored, I went online i to find something for one of the lessons I was missing. On one website, some video bloggers were talking about making their blogs. I thought ... I'm sure I could produce one people my age'd like to watch, so I did. I didn't know then it'd be such a success.\nMan: What sort of thing's your blog about?\nWoman: Well, I do lots of stuff about health and fitness, so I'm often asked by companies to review their products. In my next one, for example, I'm trying out a pair of trainers while exercising to music. That'll be more fun than the latest one I've just uploaded to the internet. It was about a kind of yoghurt which is supposed to be really good for you.\nMan: So what do you do before you record your video blog?\nWoman: I don't think too much about what I wear, and I try not to worry about what I'll say. I check my notes, but I avoid reading them aloud as I want to sound totally natural. Feeling calm's essential, so I sit quietly for a bit. Then I feel ready to record.\nMan: Are there some things you have to do every day?\nWoman: Well, the blog isn't like a personal diary - I don't blog every day. But when I do, I put links on my social media pages. Even on days when I don't post a blog, I communicate with anyone who's said something in the comments section of my videos. That's a daily event.\nMan: You also interview people on your blog ...\nWoman: Yes, I've interviewed some famous sports champions. I find them really easy to talk to. But they're not my favourite. I really like talking to people that want to make the planet a better place, especially if they're interested in the opinions of teenagers like me, because we're the future.\nMan: You made one blog called 'My Mistakes' ...\nWoman: Oh, that ... Video blogging isn't just about being popular. I like my fans to see my true character so they don't think I'm perfect. I enjoy the silly moments, like when I pronounce something incorrectly. And I also like laughing at myself. It helps me not take everything too seriously. Now listen again. [repeat]",
