        type: 'mcq',
        audio: '/audio/pet-schools2/test-4/part-4.mp3',
        transcript: "Man: Today I'm interviewing Karina Wells, a teenager who does gymnastics at a club. Karina, when did you start gymnastics lessons?\nGirl: I was four when my mum first took me to one. There were lots of children, of all different ages. The little ones were doing very basic exercises, but the older ones were doing incredible moves. I remember thinking how good they all were, but even in that first hour I learned a few things, and I was very proud of myself.\nMan: Do any of your school friends do gymnastics?\nGirl: No, but some do training in other sports. We often compare the exercises we do. They like to have a go at the jumps and other things I show them - not usually very successfully! Our different sports and hobbies give us something to talk about apart from school.\nMan: Do you do gymnastics competitions?\nGirl: Yes. I enjoy them. When I'm competing, I always remember that it's normal to be nervous. Everyone is, and we don't get too upset if we make mistakes because that happens to everyone. What's great is how nice all the gymnasts are to one another. We're all trying to win, so it's not something I'd expect.\nMan: Do you have much time for homework?\nGirl: No! Mum won't drive me to the gym until I've finished my homework, and the gym's too far away to walk, so it's the first thing I do when I get in from school. Once I left it until after a session at the gymnastics club. I was just too tired, though - I needed to go to bed. I've never tried that again.\nMan: As a gymnast, are there some things you can't eat?\nGirl: It's important I have the right diet, with plenty of fish and vegetables. I even have desserts and cakes from time to time. One thing I know isn't easy for my parents is that I need to have different meals from everyone else at home. It's a shame as I don't like giving them that extra work.\nMan: What has gymnastics taught you - apart from how to be healthy and fit?\nGirl: There's so much to do every day, and that means careful planning, so I can thank gymnastics for my skills there. There are also skills I've learned at school that help with gymnastics - such as working as part of a group. I'm good at that. Mum says I do more around the house than most 14-year-olds - like putting things away. I'm pretty sure that's nothing to do with gymnastics, though!\nMan: Thanks, Karina. Now listen again. [repeat]",
