// 全真模拟 1-8 听力原文注入（来源：官方纸质书 OCR + 人工审读，见 petMock8ListeningTranscripts.js）
(() => {
  for (const test of petListeningTests) {
    const d = PET_MOCK8_LISTENING_TRANSCRIPTS[test.meta?.id];
    if (!d) continue;
    for (const pn of ['1', '2']) {
      const items = test.parts?.[pn]?.items || [];
      const trans = d[pn === '1' ? 'p1Items' : 'p2Items'] || [];
      items.forEach((it, i) => { if (it && !it.transcript && trans[i]) it.transcript = trans[i]; });
    }
    for (const pn of ['3', '4']) {
      const part = test.parts?.[pn];
      const key = pn === '3' ? 'p3Part' : 'p4Part';
      if (part && !part.transcript && d[key]) part.transcript = d[key];
    }
  }
})();

// P1/P2 整 Part 原文归一：无整 Part transcript 且题级 transcript 齐全时，由题级顺序拼接派生（空行分隔），供结果页/专项页整 Part 原文面板使用
(() => {
  for (const test of petListeningTests) {
    const entries = Array.isArray(test.parts)
      ? test.parts.map((p, i) => [String(i + 1), p])
      : Object.entries(test.parts || {});
    for (const [, part] of entries) {
      if (!part || part.transcript) continue;
      const items = part.items || [];
      if (!items.length) continue;
      const segs = items.map((it) => it?.transcript).filter((t) => typeof t === 'string' && t.trim().length > 0);
      if (segs.length === items.length) part.transcript = segs.join('\n\n');
    }
  }
})();
